class AuthUser { final int id; final String username,email,phoneNumber; final String firstName,lastName; final bool isStaff; const AuthUser({required this.id,required this.username,required this.email,required this.phoneNumber,this.firstName='',this.lastName='',this.isStaff=false}); factory AuthUser.fromJson(Map<String,dynamic> j)=>AuthUser(id:j['id'] as int,username:j['username']??'',email:j['email']??'',phoneNumber:j['phone_number']??'',firstName:j['first_name']??'',lastName:j['last_name']??'',isStaff:j['is_staff']==true); }